const entrada = $('Edit Fields').first().json.msg?.trim().toLowerCase() || "";

// Busca números (enteros o decimales)
const matches = entrada.match(/\d+(?:[.,]\d+)?/g);

// Palabras que indican que no hay dato
const noDatoRegex = /(no tengo|no sé|no lo sé|desconozco|n\/a|ninguno)/i;

let resultado = "incorrecto";
let medida = null;

if (matches && matches.length > 0) {
  if (matches.length >= 2) {
    medida = `${matches[0]}x${matches[1]}`;
  } else {
    medida = matches[0];
  }
  resultado = "correcto";
} else if (noDatoRegex.test(entrada)) {
  resultado = "correcto";
  medida = "sin dato";
}

return [{
  json: {
    resultado,
    medida: medida || "sin dato",
    entrada_original: entrada
  }
}];

