// --- Lee el chat_id del mensaje ---
const chatId =
  $('Edit Fields').first().json.chat_id   // si vienes de "Edit Fields"
  || $json.chat_id                         // o directamente del JSON
  || '';

if (!chatId || typeof chatId !== 'string') {
  throw new Error('chat_id no está definido o no es cadena');
}

// --- Accede al Static Data global del workflow ---
const store = $getWorkflowStaticData('global');

// --- Si ya hay un id guardado para este chat, úsalo ---
let id = store[chatId];

// --- Si no existe, lo creamos (solo la 1ª vez) ---
if (!id) {
  // (Si ya generas el id en otro nodo, puedes hacer: id = $json.id;)
  const numero = chatId.substring(3, 13); // 10 dígitos del WA
  const now = new Date();
  const pad = n => String(n).padStart(2, '0');
  const y = now.getFullYear();
  const m = pad(now.getMonth() + 1);
  const d = pad(now.getDate());
  const hh = pad(now.getHours());
  const mm = pad(now.getMinutes());
  const ss = pad(now.getSeconds());
  id = `${numero}_${y}${m}${d}_${hh}{mm}${ss}`.replace('{mm}', mm); // evita colisión de llaves

  // Guarda para futuras ejecuciones de este mismo chat
  store[chatId] = id;
}

// --- Devuelve el id para el resto del flujo ---
return [{
  json: {
    ...$json,
    id,                 // <- úsalo en MySQL/Sheets
    tieneIdPrevio: !!store[chatId]
  }
}];

